#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    long long base = strtoll(argv[1], NULL, 10);
    long long exponent = strtoll(argv[2], NULL, 10);
    long long modulus = strtoll(argv[3], NULL, 10);
    if (exponent < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    if (modulus < 2) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (base < 0 || exponent < 0 || modulus < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    long long result = 1;
    base = base % modulus;
    while (exponent > 0) {
        if (exponent % 2 == 1)
            result = (result * base) % modulus;
        exponent = exponent / 2;
        base = (base * base) % modulus;
    }
    printf("result=%lld\n", result);
    return 0;
}
